// src/boot/pdfmake.js
import { boot } from "quasar/wrappers";
import pdfMake from "pdfmake/build/pdfmake";
import robotoVfs from "pdfmake/build/vfs_fonts";

// Auto-generated by scripts/build-fonts-vfs.js
import customVfs from "src/assets/fonts/fonts_vfs.js";
import customFontMap from "src/assets/fonts/fonts_map.js";

// ---------------------------------------------------------------------
// Merge our custom fonts into the VFS pdfmake uses.
//
// robotoVfs ships with pdfmake (bundled defaults).
// customVfs contains every .ttf in src/assets/fonts/.
// ---------------------------------------------------------------------
pdfMake.vfs = {
  ...robotoVfs.pdfMake.vfs,
  ...customVfs,
};

// ---------------------------------------------------------------------
// Font map
//
// Roboto stays as the fallback/default.
// Each family in customFontMap is registered automatically.
//
// Result shape:
//   pdfMake.fonts = {
//     Roboto:  { normal: "...", bold: "...", italics: "...", bolditalics: "..." },
//     Candara: { normal: "...", bold: "...", italics: "...", bolditalics: "..." },
//     Poppins: { normal: "...", bold: "...", italics: "...", bolditalics: "..." },
//   }
// ---------------------------------------------------------------------
pdfMake.fonts = {
  Roboto: {
    normal: "Roboto-Regular.ttf",
    bold: "Roboto-Medium.ttf",
    italics: "Roboto-Italic.ttf",
    bolditalics: "Roboto-MediumItalic.ttf",
  },
  ...customFontMap,
};

// Expose the list of available family names for the UI (optional)
export const availableFontFamilies = Object.keys(customFontMap);

export default boot(({ app }) => {
  app.config.globalProperties.$pdfMake = pdfMake;
});

export { pdfMake };
